// Auth POST + validation par kind.
const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok:false, _status:500, _error:'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok:false, _status:401, _error:'invalid_token' } }];
const b = $json.body || {};
const kind = String(b.kind || '').trim().toLowerCase();
const KINDS = ['ledger','wishlist','patch_ledger','patch_wishlist'];
if (!KINDS.includes(kind)) return [{ json: { _ok:false, _status:400, _error:'invalid kind' } }];

if (kind === 'ledger') {
  const r = b.row || {};
  const TYPES = ['income','expense'];
  const STATUSES = ['pending','done'];
  if (!TYPES.includes(String(r.type||'').toLowerCase())) return [{ json: { _ok:false, _status:400, _error:'invalid type' } }];
  const amt = Number(r.amount); if (!isFinite(amt) || amt <= 0) return [{ json: { _ok:false, _status:400, _error:'invalid amount' } }];
  if (!STATUSES.includes(String(r.status||'pending').toLowerCase())) return [{ json: { _ok:false, _status:400, _error:'invalid status' } }];
  if (!String(r.description||'').trim()) return [{ json: { _ok:false, _status:400, _error:'missing description' } }];
  return [{ json: { _ok:true, kind, row: {
    id: String(r.id || ('fin_'+Date.now())),
    ts: String(r.ts || new Date().toISOString()),
    type: String(r.type).toLowerCase(),
    amount: amt,
    currency: String(r.currency || 'EUR'),
    category: String(r.category || 'other').toLowerCase(),
    description: String(r.description),
    status: String(r.status || 'pending').toLowerCase(),
    due_date: String(r.due_date || ''),
    paid_at: String(r.paid_at || ''),
    created_by: String(r.created_by || ''),
    created_by_id: String(r.created_by_id || ''),
    decided_at: String(r.decided_at || ''),
    vendor: String(r.vendor || ''),
    invoice_ref: String(r.invoice_ref || ''),
    notes: String(r.notes || '')
  } } }];
}

if (kind === 'wishlist') {
  const r = b.row || {};
  if (!String(r.item || '').trim()) return [{ json: { _ok:false, _status:400, _error:'missing item' } }];
  const price = Number(r.price_estimate); if (!isFinite(price) || price < 0) return [{ json: { _ok:false, _status:400, _error:'invalid price' } }];
  return [{ json: { _ok:true, kind, row: {
    id: String(r.id || ('wl_'+Date.now())),
    ts: String(r.ts || new Date().toISOString()),
    item: String(r.item),
    category: String(r.category || 'other').toLowerCase(),
    price_estimate: price,
    priority: String(r.priority || 'medium').toLowerCase(),
    justification: String(r.justification || ''),
    recommended_by: String(r.recommended_by || ''),
    recommended_by_id: String(r.recommended_by_id || ''),
    decided: String(r.decided || 'pending').toLowerCase(),
    decided_at: String(r.decided_at || ''),
    decided_by: String(r.decided_by || ''),
    decided_by_id: String(r.decided_by_id || ''),
    linked_ledger_id: String(r.linked_ledger_id || ''),
    notes: String(r.notes || '')
  } } }];
}

// patch_ledger / patch_wishlist
const id = String(b.id || '').trim();
if (!id) return [{ json: { _ok:false, _status:400, _error:'missing id' } }];
const patch = b.patch || {};
return [{ json: { _ok:true, kind, id, patch } }];

// Merge patch into existing row, return one item (full row) for Update.
const inp = $('Auth & validate POST').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.id) === String(inp.id));
if (!row) return [{ json: { _ok:false, _status:404, _error:'ledger row not found' } }];
const p = inp.patch || {};
const merged = {
  id: row.id,
  ts: row.ts || '',
  type: p.type !== undefined ? p.type : (row.type || ''),
  amount: p.amount !== undefined ? p.amount : (row.amount || 0),
  currency: p.currency !== undefined ? p.currency : (row.currency || 'EUR'),
  category: p.category !== undefined ? p.category : (row.category || ''),
  description: p.description !== undefined ? p.description : (row.description || ''),
  status: p.status !== undefined ? p.status : (row.status || 'pending'),
  due_date: p.due_date !== undefined ? p.due_date : (row.due_date || ''),
  paid_at: p.paid_at !== undefined ? p.paid_at : (row.paid_at || ''),
  created_by: row.created_by || '',
  created_by_id: row.created_by_id || '',
  decided_at: p.decided_at !== undefined ? p.decided_at : (row.decided_at || ''),
  vendor: p.vendor !== undefined ? p.vendor : (row.vendor || ''),
  invoice_ref: p.invoice_ref !== undefined ? p.invoice_ref : (row.invoice_ref || ''),
  notes: p.notes !== undefined ? p.notes : (row.notes || '')
};
return [{ json: { _ok:true, merged } }];

const inp = $('Auth & validate POST').first().json;
const rows = $input.all().map(i => i.json);
const row = rows.find(r => String(r.id) === String(inp.id));
if (!row) return [{ json: { _ok:false, _status:404, _error:'wishlist row not found' } }];
const p = inp.patch || {};
const merged = {
  id: row.id,
  ts: row.ts || '',
  item: p.item !== undefined ? p.item : (row.item || ''),
  category: p.category !== undefined ? p.category : (row.category || ''),
  price_estimate: p.price_estimate !== undefined ? p.price_estimate : (row.price_estimate || 0),
  priority: p.priority !== undefined ? p.priority : (row.priority || 'medium'),
  justification: p.justification !== undefined ? p.justification : (row.justification || ''),
  recommended_by: row.recommended_by || '',
  recommended_by_id: row.recommended_by_id || '',
  decided: p.decided !== undefined ? p.decided : (row.decided || 'pending'),
  decided_at: p.decided_at !== undefined ? p.decided_at : (row.decided_at || ''),
  decided_by: p.decided_by !== undefined ? p.decided_by : (row.decided_by || ''),
  decided_by_id: p.decided_by_id !== undefined ? p.decided_by_id : (row.decided_by_id || ''),
  linked_ledger_id: p.linked_ledger_id !== undefined ? p.linked_ledger_id : (row.linked_ledger_id || ''),
  notes: p.notes !== undefined ? p.notes : (row.notes || '')
};
return [{ json: { _ok:true, merged } }];

const h = $json.headers || {};
const token = h['x-symbalyx-token'] || h['X-Symbalyx-Token'] || '';
const expected = $env.SYMBALYX_WEBHOOK_SECRET || '';
if (!expected) return [{ json: { _ok:false, _status:500, _error:'SYMBALYX_WEBHOOK_SECRET not configured' } }];
if (token !== expected) return [{ json: { _ok:false, _status:401, _error:'invalid_token' } }];
const q = $json.query || {};
const month = String(q.month || new Date().toISOString().slice(0,7));
return [{ json: { _ok:true, month } }];

// Calcule l'état financier (balance, runway, recommandation IA) depuis le ledger.
const month = $('Auth GET').first().json.month;
const ledger = ($('Read finance_ledger (GET)').all() || []).map(i => i.json).filter(r => r && r.id);
const wishlist = ($('Read wishlist (GET)').all() || []).map(i => i.json).filter(r => r && r.id);

const toNum = v => { const n = Number(v); return isFinite(n) ? n : 0; };
const lower = s => String(s||'').toLowerCase();

let balance = 0, monthRev = 0, monthExp = 0, pendingIn = 0, pendingOut = 0;
const monthly = {};
for (const r of ledger) {
  const type = lower(r.type), status = lower(r.status), amt = toNum(r.amount);
  if (status === 'done') {
    if (type === 'income')  balance += amt; 
    if (type === 'expense') balance -= amt;
    const ref = String(r.paid_at || r.ts || '').slice(0,7);
    if (ref === month) {
      if (type === 'income')  monthRev += amt;
      if (type === 'expense') monthExp += amt;
    }
    if (type === 'expense' && ref) {
      monthly[ref] = (monthly[ref] || 0) + amt;
    }
  } else if (status === 'pending') {
    if (type === 'income')  pendingIn  += amt;
    if (type === 'expense') pendingOut += amt;
  }
}
const recent = Object.keys(monthly).sort().slice(-3);
const burn = recent.length ? recent.reduce((s,m) => s + monthly[m], 0) / recent.length : (monthExp || 0);
const runway = burn > 0 ? balance / burn : null;

// Recommandation IA simple
const tips = [];
if (runway !== null && runway < 1) tips.push({ kind:'crit', msg:`Runway < 1 mois (${runway.toFixed(1)}). Encaisse ${pendingIn.toFixed(0)}€ en attente avant tout achat.` });
else if (runway !== null && runway < 3) tips.push({ kind:'warn', msg:`Runway court (${runway.toFixed(1)} mois). Reporte les achats wishlist non urgents.` });
else if (runway !== null && runway > 12 && balance > 5000) tips.push({ kind:'ok', msg:`Trésorerie confortable (${runway.toFixed(0)} mois). Tu peux investir.` });
if (pendingIn > 0) tips.push({ kind:'info', msg:`${pendingIn.toFixed(0)}€ à encaisser. Relance les factures impayées.` });
if (monthExp > monthRev && monthRev > 0) tips.push({ kind:'warn', msg:`Ce mois : dépenses (${monthExp.toFixed(0)}€) > revenus (${monthRev.toFixed(0)}€).` });

const wishPending = wishlist.filter(w => lower(w.decided||'pending') === 'pending');

return [{ json: {
  ok: true,
  month,
  balance: Math.round(balance * 100) / 100,
  monthly_revenue: Math.round(monthRev * 100) / 100,
  monthly_expense: Math.round(monthExp * 100) / 100,
  pending_in: Math.round(pendingIn * 100) / 100,
  pending_out: Math.round(pendingOut * 100) / 100,
  burn_rate_eur_per_month: Math.round(burn * 100) / 100,
  runway_months: runway === null ? null : Math.round(runway * 10) / 10,
  ledger_size: ledger.length,
  wishlist_pending_count: wishPending.length,
  wishlist_pending_total: Math.round(wishPending.reduce((s,w) => s + toNum(w.price_estimate), 0) * 100) / 100,
  recommendations: tips,
  generated_at: new Date().toISOString()
} }];
